    import re
    import string

    def parse_obs(obs):
        items = []
        for m in re.finditer(r'\ba ([a-z]+) (\d+)\b', obs):
            items.append((m.group(1), m.group(2)))
        return items

    # parse goal
    parts = goal.split()
    obj_type = None
    target_type = None
    for i, w in enumerate(parts):
        if w in ('in', 'on'):
            obj_type = parts[i - 1].strip(string.punctuation)
            target_type = parts[i + 1].strip(string.punctuation)
            break
    if obj_type is None:
        m = re.search(r'put a (?:\w+\s+)?(\w+) (?:in|on) (\w+)', goal, re.IGNORECASE)
        if m:
            obj_type = m.group(1).strip(string.punctuation)
            target_type = m.group(2).strip(string.punctuation)

    CONTAINERS = {'drawer', 'cabinet', 'fridge', 'microwave', 'safe', 'cupboard'}

